import{_ as e,o as i,c as a,a2 as o}from"./chunks/framework.BEmfQga0.js";const u=JSON.parse('{"title":"What is LightRSI","description":"","frontmatter":{},"headers":[],"relativePath":"getting-started/what-is-lightrsi.md","filePath":"getting-started/what-is-lightrsi.md","lastUpdated":1788258471000}'),n={name:"getting-started/what-is-lightrsi.md"};function s(r,t,l,h,d,g){return i(),a("div",null,[...t[0]||(t[0]=[o('<h1 id="what-is-lightrsi" tabindex="-1">What is LightRSI <a class="header-anchor" href="#what-is-lightrsi" aria-label="Permalink to &quot;What is LightRSI&quot;">​</a></h1><p>LightRSI is a <strong>modular runtime for recursive improvement in long-running LLM agents</strong>. It provides the shared lifecycle, state, safety, observability, and host integration needed to build an improvement capability once and run it across OpenClaw, Codex, Claude Code, and future hosts. The current implementation focuses on context and agentic memory.</p><h2 id="lightrsi-vs-tokenpilot" tabindex="-1">LightRSI vs. TokenPilot <a class="header-anchor" href="#lightrsi-vs-tokenpilot" aria-label="Permalink to &quot;LightRSI vs. TokenPilot&quot;">​</a></h2><p>A common point of confusion: LightRSI and TokenPilot are not the same thing.</p><table tabindex="0"><thead><tr><th style="text-align:left;"></th><th style="text-align:left;">LightRSI</th><th style="text-align:left;">TokenPilot</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>What it is</strong></td><td style="text-align:left;">A recursive-improvement runtime and platform</td><td style="text-align:left;">A preset that runs on LightRSI</td></tr><tr><td style="text-align:left;"><strong>Role</strong></td><td style="text-align:left;">Loads, manages, and executes plugins</td><td style="text-align:left;">Provides cache-aware context management</td></tr><tr><td style="text-align:left;"><strong>Scope</strong></td><td style="text-align:left;">Platform-wide: plugins, adapters, CLI</td><td style="text-align:left;">One specific capability: reducing token usage</td></tr><tr><td style="text-align:left;"><strong>Status</strong></td><td style="text-align:left;">Active development</td><td style="text-align:left;">Stable — the first official plugin</td></tr></tbody></table><p>LightRSI provides the reusable runtime boundary; TokenPilot supplies one concrete policy bundle for cache-efficient context management.</p><h2 id="what-problems-it-solves" tabindex="-1">What Problems It Solves <a class="header-anchor" href="#what-problems-it-solves" aria-label="Permalink to &quot;What Problems It Solves&quot;">​</a></h2><ul><li><strong>Long sessions get expensive</strong>. As agent sessions grow, every turn carries more context, which means more tokens and higher costs.</li><li><strong>Context is repetitive</strong>. Much of what gets sent to the model each turn is identical to the previous turn — wasteful if not cached.</li><li><strong>Tool output is noisy</strong>. Large tool responses can pollute future turns with irrelevant data.</li><li><strong>Sessions don&#39;t prune themselves</strong>. Without eviction, old context accumulates until sessions hit limits or become too slow.</li></ul><p>LightRSI addresses these through its plugin model. TokenPilot, the first plugin, implements the runtime policies: stable-prefix rewriting, context reduction, and lifecycle-aware eviction.</p><h2 id="what-it-doesn-t-solve" tabindex="-1">What It Doesn&#39;t Solve <a class="header-anchor" href="#what-it-doesn-t-solve" aria-label="Permalink to &quot;What It Doesn&#39;t Solve&quot;">​</a></h2><ul><li><strong>Short, single-turn interactions</strong>. If your sessions are always one-shot, there is nothing for caching or eviction to optimize.</li><li><strong>Model quality or accuracy</strong>. LightRSI doesn&#39;t change model behavior — it changes what context gets sent to the model.</li><li><strong>All memory problems</strong>. Long-term memory is an experimental feature area; TokenPilot focuses on the current session&#39;s context window.</li></ul><h2 id="relationship-to-the-paper" tabindex="-1">Relationship to the Paper <a class="header-anchor" href="#relationship-to-the-paper" aria-label="Permalink to &quot;Relationship to the Paper&quot;">​</a></h2><p>The <a href="https://arxiv.org/abs/2606.17016" target="_blank" rel="noreferrer">TokenPilot paper</a> describes the cache-efficient context management technique. LightRSI is the platform that hosts TokenPilot as its first plugin, and will host additional plugins in the future.</p><h2 id="next-steps" tabindex="-1">Next Steps <a class="header-anchor" href="#next-steps" aria-label="Permalink to &quot;Next Steps&quot;">​</a></h2><ul><li><a href="/LightRSI/getting-started/quick-start">Quick Start</a> — get running in under 5 minutes</li><li><a href="/LightRSI/platform-concepts/core-runtime">Core Concepts</a> — understand the platform architecture</li><li><a href="/LightRSI/plugin-catalog/tokenpilot/overview">TokenPilot Overview</a> — dive into the featured plugin</li></ul>',15)])])}const p=e(n,[["render",s]]);export{u as __pageData,p as default};
